      en: [],
      es: ["Fundada en 1935", "Produce el 40% del paladio mundial", "Ubicada en la península de Taimyr", "Temperaturas invernales de hasta -50°C", "Exportaciones vía puerto de Dudinka", "Principal proveedor de níquel de alta calidad"],
      pt: ["Fundada em 1935", "Produz 40% do paládio global", "Localizada na Península de Taimyr", "Temperaturas no inverno atingem -50°C", "Exportações via porto de Dudinka", "Grande fornecedor de níquel de alta qualidade"],
