imageHint: "Skyscrapers of Moscow City international business district",
    descriptionAdvanced: {
      de: "Das Moskau City Geschäftsviertel (offiziell das Internationale Geschäftszentrum Moskau) ist ein architektonisches Symbol des modernen, kapitalistischen Russlands. Auf einem ehemaligen Industriegebiet von etwa 60 Hektar am Presnenskaja-Ufer der Moskwa konzipiert, vereint das Viertel einige der kühnsten Wolkenkratzerdesigns Europas. Zu den markantesten Strukturen zählen der Federation Tower mit 374 Metern Höhe, der spiralförmige Evolution Tower und der Mercury City Tower mit seiner kupferfarbenen Glasfassade. Das Projekt wurde 1992 initiiert, und nach Jahrzehnten der Bautätigkeit ist es heute das pulsierende Finanzherz des Landes. Hier befinden sich die Hauptquartiere staatlicher Ministerien, führender russischer Banken wie VTB und Sberbank sowie zahlreicher multinationaler Konzerne. Mit geschätzten 300.000 Menschen, die täglich in diesem Komplex arbeiten, wohnen oder einkaufen, fungiert Moskau City als autarke vertikale Stadt, tief integriert in das U-Bahn-Netz und durch eigene Brücken mit dem Rest der Hauptstadt verbunden.",
      hu: "A Moszkva-City üzleti negyed (hivatalos nevén a Moszkvai Nemzetközi Üzleti Központ) a modern, kapitalista Oroszország építészeti szimbóluma. A Moszkva folyó Presznyenszkaja rakpartján, egy mintegy 60 hektáros egykori iparterületen kialakított negyed Európa legmerészebb felhőkarcoló-dizájnjait egyesíti. A legszembetűnőbb építmények közé tartozik a 374 méter magas Föderáció Torony, a spirális alakú Evolúció Torony és a rézszínű üveghomlokzatú Mercury City Torony. A projektet 1992-ben indították el, és a több évtizedes építkezés után ma ez az ország lüktető pénzügyi szíve. Itt található számos állami minisztérium, a vezető orosz bankok (mint a VTB és a Sberbank), valamint számos multinacionális vállalat székhelye. A becslések szerint naponta mintegy 300 000 ember dolgozik, él vagy vásárol ebben a komplexumban, így a Moszkva-City önellátó vertikális városként funkcionál, amely szorosan integrálódott a metróhálózatba és saját hidakkal kapcsolódik a főváros többi részéhez.",
      ro: "Centrul Internațional de Afaceri din Moscova (Moscow City) este un simbol arhitectural al Rusiei moderne și capitaliste. Conceput pe o fostă zonă industrială de aproximativ 60 de hectare pe cheiul Presnenskaia al râului Moscova, cartierul reunește unele dintre cele mai îndrăznețe designuri de zgârie-nori din Europa. Printre cele mai frapante structuri se numără Turnul Federației, cu o înălțime de 374 de metri, Turnul Evoluției în formă de spirală și Turnul Mercury City, cu fațada sa din sticlă arămie. Proiectul a fost inițiat în 1992, iar după decenii de construcție, este astăzi inima financiară vibrantă a țării. Aici se află sediile ministerelor de stat, ale marilor bănci rusești, precum VTB și Sberbank, precum și ale numeroaselor corporații multinaționale. Cu o estimare de 300.000 de persoane care lucrează, locuiesc sau fac cumpărături zilnic în acest complex, Moscow City funcționează ca un oraș vertical autonom, profund integrat în rețeaua de metrou și conectat la restul capitalei prin poduri proprii.",
      en: "The Moscow City Business District (officially the Moscow International Business Center) is an architectural symbol of modern, capitalist Russia. Conceived on a former industrial zone of approximately 60 hectares on the Presnenskaya Embankment of the Moskva River, the district unites some of the most daring skyscraper designs in Europe. Among the most striking structures are the 374-meter-tall Federation Tower, the spiral-shaped Evolution Tower, and the Mercury City Tower with its copper-colored glass facade. The project was initiated in 1992, and after decades of construction, it is today the pulsing financial heart of the country. It houses the headquarters of state ministries, leading Russian banks like VTB and Sberbank, and numerous multinational corporations. With an estimated 300,000 people working, living, or shopping in this complex daily, Moscow City functions as a self-sufficient vertical city, deeply integrated into the metro network and connected to the rest of the capital via its own bridges.",
      es: "El distrito de negocios Moscú City (oficialmente Centro Internacional de Negocios de Moscú) es un símbolo arquitectónico de la Rusia capitalista moderna. Concebido en una antigua zona industrial de unas 60 hectáreas en el muelle Presnenskaya del río Moscova, el distrito reúne algunos de los diseños de rascacielos más audaces de Europa. Entre sus estructuras más destacadas se encuentran la Torre Federación con 374 metros de altura, la espiral de la Torre Evolución y la Torre Mercury City con su fachada de vidrio color cobre. El proyecto se inició en 1992 y, tras décadas de construcción, hoy es el corazón financiero pulsante del país. Aquí se encuentran las sedes de ministerios estatales, bancos rusos líderes como VTB y Sberbank, y numerosas multinacionales. Con unas 300.000 personas que trabajan, viven o compran diariamente en el complejo, Moscú City funciona como una ciudad vertical autosuficiente, integrada en la red de metro y conectada por sus propios puentes con el resto de la capital.",
      pt: "O distrito de negócios Moscou City (oficialmente Centro Internacional de Negócios de Moscou) é um símbolo arquitetônico da Rússia moderna e capitalista. Projetado em uma antiga área industrial de cerca de 60 hectares na margem Presnenskaya do rio Moscou, o bairro reúne alguns dos designs de arranha-céus mais ousados da Europa. Entre as estruturas mais marcantes estão a Federation Tower, com 374 metros de altura, a espiral Evolution Tower e a Mercury City Tower, com sua fachada de vidro cor de cobre. O projeto foi iniciado em 1992 e, após décadas de construção, é hoje o coração financeiro pulsante do país. Aqui localizam-se as sedes de ministérios estatais, de bancos russos líderes como o VTB e o Sberbank, além de inúmeras multinacionais. Com cerca de 300.000 pessoas que trabalham, vivem ou fazem compras diariamente no complexo, Moscou City funciona como uma cidade vertical autossuficiente, integrada à rede de metrô e conectada por pontes próprias ao resto da capital.",
      fr: "Le quartier d'affaires Moscou City (officiellement le Centre d'affaires international de Moscou) est un symbole architectural de la Russie capitaliste moderne. Conçu sur une ancienne zone industrielle d'environ 60 hectares sur le quai Presnenskaïa de la Moskova, le quartier réunit certains des gratte-ciel les plus audacieux d'Europe. Parmi les structures les plus marquantes figurent la tour de la Fédération (374 mètres), la tour Évolution en forme de spirale et la Mercury City Tower avec sa façade en verre cuivré. Initié en 1992, le projet est devenu après des décennies de travaux le cœur financier battant du pays. On y trouve les sièges de ministères, de grandes banques russes comme VTB et Sberbank, ainsi que de nombreuses multinationales. Avec environ 300 000 personnes y travaillant, y vivant ou y faisant leurs achats quotidiennement, Moscou City fonctionne comme une ville verticale autosuffisante, intégrée au réseau de métro et reliée au reste de la capitale par ses propres ponts.",
    },
