    name: { de: "Kamaz LKW-Werk", hu: "Kamaz teherautógyár", ro: "Fabrica de camioane Kamaz", en: "Kamaz Truck Plant"},
    image: "/poi-images/russia-kamaz-factory-economic-v2.webp",
