      fr: ["Découverte en 1955 par des géologues", "Située dans la République de Sakha (Iakoutie)", "Cratère de 525 mètres de profondeur", "1 200 mètres de diamètre", "Exploitée par l'entreprise publique Alrosa", "Espace aérien fermé aux hélicoptères"],
