      pt: ["Fundado na década de 1840", "Maior porto russo do Mar Negro", "Opera livre de gelo todo o ano", "Crucial para exportações de petróleo e cereais", "Capacidade de águas profundas para superpetroleiros", "Partilha o local com uma base naval"],
