      pt: ["Barragem de arco-gravidade com 242 metros de altura", "Capacidade instalada de 6.400 MW", "Localizada no rio Ienissei", "Construção iniciada em 1968", "Abastece grandes fundições de alumínio", "Recuperada de um grande acidente em 2009"],
