      de: "Surgut gilt als die 'Ölhauptstadt' Russlands. Die Wirtschaft der Stadt wird von der Öl- und Gasförderung sowie der Stromerzeugung dominiert.",
      hu: "Szurgutot Oroszország „olajfővárosaként” emlegetik. A város gazdaságát az olaj- és gázkitermelés, valamint az energiatermelés uralja.",
      ro: "Surgut este considerată „capitala petrolului” a Rusiei. Economia orașului este dominată de extracția de petrol și gaze și de producția de energie.",
      en: "Surgut is often called the 'oil capital' of Russia. The city's economy is dominated by oil and gas extraction and power generation.",
      es: "Surgut es considerada la 'capital del petróleo' de Rusia. La economía de la ciudad está dominada por la extracción de petróleo y gas, así como por la generación de electricidad.",
