      pt: ["Sede da Surgutneftegas", "Centro da Sibéria Ocidental", "Grandes centrais elétricas", "Importante nó ferroviário"],
      fr: ["Siège de Surgutneftegas", "Centre de la Sibérie occidentale", "Grandes centrales électriques", "Important nœud ferroviaire"],
