imageHint: "Oil refinery and industrial skyline of Surgut",
    descriptionAdvanced: {
      de: "Das Erdölzentrum Surgut ist das pochende wirtschaftliche Herz der Region Chanty-Mansijsk und fungiert als die unangefochtene 'Ölhauptstadt' der Russischen Föderation. Die Stadt erlebte in den 1960er Jahren ein explosionsartiges Wachstum, als in den umliegenden westsibirischen Sumpfgebieten enorme Kohlenwasserstoffreserven entdeckt wurden. Heute ist Surgut der Hauptsitz des Energiegiganten Surgutneftegas, einem der profitabelsten und einflussreichsten Ölförderer des Landes, der täglich Millionen Barrel Rohöl aus den tieferen Gesteinsschichten pumpt. Neben der Förderung ist die Stadt auch ein gigantisches Zentrum für die Stromerzeugung; die riesigen Kraftwerke Surgut-1 und Surgut-2 gehören zu den leistungsstärksten thermischen Kraftwerken der Welt und nutzen begleitendes Erdgas als primären Brennstoff. Die massive Infrastruktur, bestehend aus Hunderten von Bohrinseln, Pipelines und logistischen Knotenpunkten, sichert einen erheblichen Teil der gesamten russischen Staatseinnahmen und macht Surgut zu einer der reichsten Städte jenseits des Urals.",
      hu: "A Szurgut olajipari központ Hanti- és Manysiföld lüktető gazdasági szíve, és egyben az Oroszországi Föderáció vitathatatlan „olajfővárosa”. A város az 1960-as években robbanásszerű fejlődésnek indult, amikor a környező nyugat-szibériai mocsaras területeken hatalmas szénhidrogén-készleteket fedeztek fel. Ma Szurgut ad otthont a Szurgutnyeftegaz energiai óriásvállalatnak, az ország egyik legjövedelmezőbb és legbefolyásosabb olajkitermelőjének, amely naponta több millió hordó kőolajat szivattyúz fel a mélyebb kőzetrétegekből. A kitermelés mellett a város az energiatermelés hatalmas központja is; a Szurgut-1 és Szurgut-2 óriáserőművek a világ legnagyobb teljesítményű hőerőművei közé tartoznak, amelyek elsődleges tüzelőanyagként a kísérő földgázt használják. A több száz fúrótoronyból, csővezetékekből és logisztikai csomópontokból álló masszív infrastruktúra az orosz állami bevételek jelentős részét biztosítja, így Szurgut az Urálon túli terület egyik leggazdagabb városává vált.",
      ro: "Centrul petrolier Surgut este inima economică palpitantă a districtului autonom Hantî-Mansiisk și funcționează ca „capitala necontestată a petrolului” din Federația Rusă. Orașul a cunoscut o creștere explozivă în anii 1960, când rezerve enorme de hidrocarburi au fost descoperite în mlaștinile înconjurătoare din vestul Siberiei. Astăzi, Surgut este sediul central al gigantului energetic Surgutneftegas, unul dintre cei mai profitabili și influenți producători de petrol din țară, care pompează zilnic milioane de barili de țiței din straturile adânci de rocă. Pe lângă extracție, orașul este și un centru gigantic pentru producția de energie electrică; centralele masive Surgut-1 și Surgut-2 se numără printre cele mai puternice centrale termice din lume, utilizând gazul natural asociat ca combustibil principal. Infrastructura masivă, formată din sute de platforme de foraj, conducte și noduri logistice, asigură o parte semnificativă din veniturile totale ale statului rus și face din Surgut unul dintre cele mai bogate orașe de dincolo de Urali.",
      en: "The Surgut Oil and Gas Hub is the beating economic heart of the Khanty-Mansi Autonomous Okrug and functions as the undisputed 'oil capital' of the Russian Federation. The city experienced explosive growth in the 1960s when enormous hydrocarbon reserves were discovered in the surrounding West Siberian swamps. Today, Surgut is the headquarters of the energy giant Surgutneftegas, one of the most profitable and influential oil producers in the country, pumping millions of barrels of crude oil daily from deeper rock layers. In addition to extraction, the city is also a gigantic center for power generation; the massive Surgut-1 and Surgut-2 power stations are among the most powerful thermal power plants in the world, utilizing associated natural gas as their primary fuel. The massive infrastructure, consisting of hundreds of drilling rigs, pipelines, and logistical nodes, secures a significant portion of Russia's total state revenues and makes Surgut one of the wealthiest cities beyond the Urals.",
      es: "El centro petrolero de Surgut es el corazón económico de la región de Janty-Mansi y funciona como la indiscutible 'capital del petróleo' de la Federación Rusa. La ciudad experimentó un crecimiento explosivo en la década de 1960, cuando se descubrieron enormes reservas de hidrocarburos en los pantanos circundantes de Siberia occidental. Hoy en día, Surgut es la sede del gigante energético Surgutneftegas, uno de los productores de petróleo más rentables e influyentes del país, que bombea diariamente millones de barriles de crudo. Además de la extracción, la ciudad es un centro gigantesco para la generación de electricidad; las enormes centrales eléctricas Surgut-1 y Surgut-2 se encuentran entre las centrales térmicas más potentes del mundo y utilizan gas natural asociado como combustible principal. La infraestructura masiva, compuesta por cientos de plataformas de perforación, oleoductos y nodos logísticos, asegura una parte considerable de los ingresos estatales rusos totales y convierte a Surgut en una de las ciudades más ricas más allá de los Urales.",
      pt: "O centro de petróleo de Surgut é o coração económico pulsante da região de Khanty-Mansi e funciona como a indiscutível 'capital do petróleo' da Federação Russa. A cidade viveu um crescimento explosivo na década de 1960, quando foram descobertas enormes reservas de hidrocarbonetos nas áreas pantanosas circundantes da Sibéria Ocidental. Hoje, Surgut é a sede da gigante energética Surgutneftegas, um dos produtores de petróleo mais rentáveis e influentes do país, que bombeia diariamente milhões de barris de petróleo bruto das camadas rochosas profundas. Além da extração, a cidade é também um centro gigantesco de produção de eletricidade; as enormes centrais elétricas Surgut-1 e Surgut-2 estão entre as centrais térmicas mais potentes do mundo e utilizam o gás natural associado como combustível primário. A infraestrutura massiva, composta por centenas de plataformas de perfuração, oleodutos e nós logísticos, assegura uma parte significativa das receitas totais do Estado russo e faz de Surgut uma das cidades mais ricas para além dos Urais.",
      fr: "Le centre pétrolier de Surgut est le cœur économique battant de la région de Khanty-Mansi et fait office de « capitale du pétrole » incontestée de la Fédération de Russie. La ville a connu une croissance explosive dans les années 1960, lorsque d'énormes réserves d'hydrocarbures ont été découvertes dans les zones marécageuses environnantes de Sibérie occidentale. Aujourd'hui, Surgut est le siège du géant de l'énergie Surgutneftegas, l'un des producteurs de pétrole les plus rentables et les plus influents du pays, pompant chaque jour des millions de barils de pétrole brut. Outre l'extraction, la ville est également un centre gigantesque pour la production d'électricité ; les énormes centrales électriques Surgut-1 et Surgut-2 comptent parmi les centrales thermiques les plus puissantes au monde et utilisent le gaz naturel associé comme combustible primaire. L'infrastructure massive, composée de centaines de derricks, de pipelines et de nœuds logistiques, garantit une part substantielle des recettes totales de l'État russe et fait de Surgut l'une des villes les plus riches au-delà de l'Oural.",
    },
