      pt: ["Sede da gigante energética Surgutneftegas", "Crescimento rápido iniciado na década de 1960", "Localizada na região de Khanty-Mansi", "Acolhe as centrais elétricas Surgut-1 e Surgut-2", "Conhecida como a capital do petróleo da Rússia", "Gera receitas estatais significativas"],
