      pt: ["A maior refinaria da Rússia por capacidade", "Comissionada em 1955", "Propriedade da Gazprom Neft", "Produz diesel de grau ártico", "Craqueamento catalítico altamente avançado", "Localizada na Sibéria Ocidental"],
