imageHint: "Bratsk aluminum smelter industrial buildings",
    descriptionAdvanced: {
      de: "Die Aluminiumhütte Bratsk im fernöstlichen Irkutsker Gebiet ist ein Industriegigant und nachweislich die größte Produktionsanlage für Primäraluminium auf dem Planeten. Das Werk, das 1966 seinen Betrieb aufnahm, wurde bewusst in unmittelbarer Nähe des gewaltigen Bratsker Wasserkraftwerks errichtet, da die Schmelzelefktrolyse von Bauxit zu Aluminium unglaubliche Mengen an billiger elektrischer Energie erfordert. Die Hütte verschlingt fast die gesamte Produktion des Staudamms und produziert jährlich rund eine Million Tonnen des begehrten Leichtmetalls. Das von RUSAL betriebene Werk ist eine maßgebliche Stütze der russischen Exportwirtschaft, wobei die Metalle an Automobilhersteller, Flugzeugbauer und Verpackungsindustrien auf der ganzen Welt geliefert werden. Trotz enormer Fortschritte in der Umwelttechnik bleibt die Minderung der fluorierten Emissionen aus den Hunderten von Elektrolysezellen eine andauernde technologische Herausforderung, der sich der Komplex in den rauen Bedingungen Ostsibiriens stellen muss.",
      hu: "A távol-keleti Irkutszki területen található Bratszki alumíniumkohó egy ipari óriás, és bizonyítottan a bolygó legnagyobb primer alumíniumot előállító üzeme. Az 1966-ban üzembe helyezett gyárat tudatosan a hatalmas Bratszki vízerőmű közvetlen közelében építették fel, mivel a bauxit alumíniummá történő olvasztóelektrolízise elképesztő mennyiségű olcsó elektromos energiát igényel. A kohó szinte a gát teljes áramtermelését felemészti, és évente mintegy egymillió tonnát állít elő a keresett könnyűfémből. A RUSAL által üzemeltetett gyár az orosz exportgazdaság egyik meghatározó pillére; a fémet a világ minden tájára szállítják autógyártóknak, repülőgépgyáraknak és csomagolóipari vállalatoknak. A környezetvédelmi technológiában elért hatalmas előrelépések ellenére a több száz elektrolíziscellából származó fluorozott kibocsátások csökkentése folyamatos technológiai kihívás marad, amellyel a komplexumnak szembe kell néznie Kelet-Szibéria zord körülményei között.",
      ro: "Topitoria de aluminiu Bratsk, din regiunea Irkuțk din Extremul Orient, este un gigant industrial și, în mod demonstrabil, cea mai mare instalație de producție a aluminiului primar de pe planetă. Uzina, care și-a început activitatea în 1966, a fost construită în mod deliberat în imediata vecinătate a uriașei hidrocentrale Bratsk, deoarece electroliza topiturii bauxitei pentru a produce aluminiu necesită cantități incredibile de energie electrică ieftină. Topitoria consumă aproape întreaga producție de energie a barajului, producând anual aproximativ un milion de tone din acest metal ușor foarte căutat. Operată de RUSAL, uzina este un pilon esențial al economiei de export a Rusiei, metalele fiind furnizate producătorilor de automobile, avioane și companiilor de ambalaje din întreaga lume. În ciuda progreselor enorme în domeniul tehnologiei de mediu, reducerea emisiilor de gaze fluorurate de la sutele de celule de electroliză rămâne o provocare tehnologică continuă, pe care complexul trebuie să o gestioneze în condițiile aspre din Siberia de Est.",
      en: "The Bratsk Aluminum Smelter in the Far Eastern Irkutsk Oblast is an industrial giant and demonstrably the largest primary aluminum production facility on the planet. The plant, which began operations in 1966, was deliberately built in the immediate vicinity of the massive Bratsk Hydroelectric Station, because the electrolytic smelting of bauxite to produce aluminum requires incredible amounts of cheap electrical energy. The smelter consumes almost the entire power output of the dam, producing around one million tons of the sought-after light metal annually. Operated by RUSAL, the plant is a critical pillar of Russia's export economy, with the metal supplied to automakers, aerospace companies, and packaging industries around the world. Despite enormous progress in environmental technology, mitigating the fluorinated emissions from its hundreds of electrolysis cells remains an ongoing technological challenge that the complex must address in the harsh conditions of Eastern Siberia.",
      es: "La fundición de aluminio de Bratsk, en la región de Irkutsk, es un gigante industrial y la planta de producción de aluminio primario más grande del planeta. La planta, que comenzó a operar en 1966, se construyó deliberadamente cerca de la enorme central hidroeléctrica de Bratsk, ya que la electrólisis para convertir bauxita en aluminio requiere cantidades increíbles de energía eléctrica barata. La fundición consume casi toda la producción de la presa y produce anualmente alrededor de un millón de toneladas del codiciado metal ligero. La planta, operada por RUSAL, es un pilar fundamental de la economía de exportación rusa, suministrando metales a fabricantes de automóviles, constructores de aviones e industrias de embalaje en todo el mundo. A pesar de los enormes avances en tecnología ambiental, la reducción de las emisiones de flúor de los cientos de cubas electrolíticas sigue siendo un desafío tecnológico constante en las duras condiciones de Siberia Oriental.",
      pt: "A fundição de alumínio de Bratsk, na região de Irkutsk, é um gigante industrial e comprovadamente a maior instalação de produção de alumínio primário do planeta. A fábrica, que iniciou as suas operações em 1966, foi deliberadamente construída na proximidade imediata da enorme central hidroelétrica de Bratsk, uma vez que a eletrólise de bauxite em alumínio requer quantidades inacreditáveis de energia elétrica barata. A fundição consome quase toda a produção da barragem e produz anualmente cerca de um milhão de toneladas do cobiçado metal leve. A fábrica, operada pela RUSAL, é um pilar decisivo da economia de exportação russa, sendo os metais fornecidos a fabricantes de automóveis, construtores de aviões e indústrias de embalagens em todo o mundo. Apesar dos enormes progressos na tecnologia ambiental, a redução das emissões de flúor das centenas de células eletrolíticas continua a ser um desafio tecnológico contínuo nas duras condições da Sibéria Oriental.",
      fr: "La fonderie d'aluminium de Bratsk, dans l'oblast d'Irkoutsk, est un géant industriel et la plus grande usine de production d'aluminium primaire de la planète. L'usine, qui a débuté ses activités en 1966, a été délibérément construite à proximité immédiate du gigantesque barrage de Bratsk, car l'électrolyse de l'alumine nécessite des quantités incroyables d'énergie électrique bon marché. La fonderie absorbe la quasi-totalité de la production du barrage et produit chaque année environ un million de tonnes de ce métal léger convoité. Exploitée par RUSAL, l'usine est un pilier majeur de l'économie d'exportation russe, fournissant des constructeurs automobiles, des avionneurs et des industries de l'emballage dans le monde entier. Malgré d'importants progrès environnementaux, la réduction des émissions fluorées des centaines de cuves d'électrolyse reste un défi technologique permanent dans les conditions rudes de la Sibérie orientale.",
    },
