imageHint: "Beloyarsk nuclear power plant reactors and cooling towers",
    descriptionAdvanced: {
      de: "Das Kernkraftwerk Belojarsk nahe Saretschny (Oblast Swerdlowsk) nimmt in der globalen Nuklearindustrie eine absolute Sonderstellung ein. Benannt nach dem sowjetischen Atomphysiker Igor Kurtschatow, ist es die einzige Einrichtung der Welt, die erfolgreich kommerzielle Schnelle Brutreaktoren betreibt. Der Meilenstein wurde mit dem BN-600-Reaktor gesetzt, dem später der leistungsstärkere BN-800-Reaktor folgte. Diese revolutionäre Technologie ermöglicht nicht nur eine wesentlich effizientere Nutzung des Uranbrennstoffs, sondern auch das Recycling von abgebranntem Kernbrennstoff aus herkömmlichen Leichtwasserreaktoren, was den radioaktiven Abfall signifikant reduziert. Belojarsk ist damit das operative Herzstück des russischen Programms zur Schließung des nuklearen Brennstoffkreislaufs. Die Anlage produziert zuverlässig riesige Mengen an Grundlaststrom für die hochindustrialisierte Ural-Region. Angesichts seiner experimentellen Ursprünge und seines kommerziellen Erfolgs wird Belojarsk häufig von internationalen Nuklearexperten besucht, die die Zukunft der Kernenergie studieren.",
      hu: "A Zarecsnij (Szverdlovszki terület) közelében fekvő Belojarszki atomerőmű abszolút egyedülálló helyet foglal el a globális nukleáris iparban. Az Igor Kurcsatov szovjet atomfizikusról elnevezett létesítmény az egyetlen a világon, amely sikeresen üzemeltet kereskedelmi célú gyors tenyésztőreaktorokat. A mérföldkövet a BN-600-as reaktorral érték el, amelyet később a nagyobb teljesítményű BN-800-as reaktor követett. Ez a forradalmi technológia nemcsak az urán üzemanyag sokkal hatékonyabb felhasználását teszi lehetővé, hanem a hagyományos könnyűvizes reaktorokból származó kiégett nukleáris fűtőelemek újrahasznosítását is, ami jelentősen csökkenti a radioaktív hulladék mennyiségét. A Belojarszki erőmű ezáltal a nukleáris üzemanyagciklus lezárására irányuló orosz program operatív szíve. A létesítmény megbízhatóan hatalmas mennyiségű alaperőművi áramot termel az erősen iparosodott Urál régió számára. Kísérleti gyökerei és kereskedelmi sikere miatt Belojarszkot gyakran látogatják az atomenergia jövőjét tanulmányozó nemzetközi nukleáris szakértők.",
      ro: "Centrala nucleară Beloiarsk, situată lângă Zarecinîi (regiunea Sverdlovsk), ocupă o poziție absolut unică în industria nucleară globală. Numită după fizicianul nuclear sovietic Igor Kurceatov, este singura unitate din lume care operează cu succes reactoare comerciale cu neutroni rapizi (breeder reactors). Etapa istorică a fost marcată de reactorul BN-600, urmat ulterior de reactorul BN-800, mult mai puternic. Această tehnologie revoluționară permite nu numai o utilizare mult mai eficientă a combustibilului de uraniu, ci și reciclarea combustibilului nuclear uzat de la reactoarele convenționale cu apă ușoară, reducând semnificativ deșeurile radioactive. Beloiarsk este astfel inima operațională a programului rus de închidere a ciclului combustibilului nuclear. Centrala produce cu fiabilitate cantități masive de energie de bază pentru regiunea puternic industrializată a Uralilor. Datorită originilor sale experimentale și succesului comercial, Beloiarsk este vizitată frecvent de experți nucleari internaționali care studiază viitorul energiei nucleare.",
      en: "The Beloyarsk Nuclear Power Station, located near Zarechny (Sverdlovsk Oblast), holds an absolutely unique position in the global nuclear industry. Named after the Soviet nuclear physicist Igor Kurchatov, it is the only facility in the world that successfully operates commercial fast breeder reactors. The milestone was set with the BN-600 reactor, which was later followed by the more powerful BN-800 reactor. This revolutionary technology not only allows for a much more efficient use of uranium fuel but also the recycling of spent nuclear fuel from conventional light-water reactors, significantly reducing radioactive waste. Beloyarsk is thus the operational heart of the Russian program to close the nuclear fuel cycle. The plant reliably produces massive amounts of baseload electricity for the highly industrialized Ural region. Given its experimental origins and commercial success, Beloyarsk is frequently visited by international nuclear experts studying the future of nuclear energy.",
      es: "La central nuclear de Beloyarsk, cerca de Zarechny (Óblast de Sverdlovsk), ocupa una posición absolutamente especial en la industria nuclear mundial. Nombrada en honor al físico atómico soviético Ígor Kurchátov, es la única instalación en el mundo que opera con éxito reactores comerciales de reproducción rápida. El hito se estableció con el reactor BN-600, al que siguió más tarde el más potente BN-800. Esta tecnología revolucionaria permite no solo un uso mucho más eficiente del combustible de uranio, sino también el reciclaje de combustible nuclear gastado de los reactores de agua ligera convencionales, lo que reduce significativamente los residuos radiactivos. Beloyarsk es, por tanto, el corazón operativo del programa ruso para cerrar el ciclo del combustible nuclear. La planta produce de forma fiable enormes cantidades de electricidad de carga base para la región altamente industrializada de los Urales y es visitada frecuentemente por expertos internacionales para estudiar el futuro de la energía nuclear.",
      pt: "A central nuclear de Beloyarsk, perto de Zarechny (Oblast de Sverdlovsk), ocupa uma posição absolutamente especial na indústria nuclear global. Batizada em homenagem ao físico atómico soviético Igor Kurchatov, é a única instalação no mundo que opera com sucesso reatores comerciais de reprodução rápida. O marco foi estabelecido com o reator BN-600, ao qual se seguiu mais tarde o reator BN-800, mais potente. Esta tecnologia revolucionária permite não só uma utilização muito mais eficiente do combustível de urânio, mas também a reciclagem de combustível nuclear gasto de reatores convencionais de água leve, o que reduz significativamente os resíduos radioativos. Beloyarsk é, portanto, o coração operacional do programa russo para o fecho do ciclo do combustível nuclear. A instalação produz de forma fiável enormes quantidades de eletricidade de carga de base para a região altamente industrializada dos Urais e é frequentemente visitada por especialistas internacionais para estudar o futuro da energia nuclear.",
      fr: "La centrale nucléaire de Beloïarsk, près de Zaretchny (oblast de Sverdlovsk), occupe une place absolument unique dans l'industrie nucléaire mondiale. Nommée d'après le physicien nucléaire soviétique Igor Kourtchatov, c'est la seule installation au monde exploitant avec succès des réacteurs à neutrons rapides commerciaux. Le premier jalon a été posé avec le réacteur BN-600, suivi plus tard par le réacteur BN-800 plus puissant. Cette technologie révolutionnaire permet non seulement une utilisation beaucoup plus efficace de l'uranium, mais aussi le recyclage du combustible nucléaire usé provenant des réacteurs à eau légère conventionnels, réduisant ainsi considérablement les déchets radioactifs. Beloïarsk est donc le cœur opérationnel du programme russe visant à fermer le cycle du combustible nucléaire. L'installation produit de manière fiable d'énormes quantités d'électricité de base pour la région hautement industrialisée de l'Oural et est fréquemment visitée par des experts internationaux étudiant l'avenir de l'énergie nucléaire.",
    },
