      es: ["Ubicado en la península de Kola", "Puerto más grande del mundo al norte del Círculo Ártico", "Libre de hielo todo el año por la Corriente del Golfo", "Terminal occidental de la Ruta del Mar del Norte", "Centro principal de exportación de carbón y fertilizantes", "Base de la flota de rompehielos nucleares de Rusia"],
      pt: ["Localizado na Península de Kola", "Maior porto do mundo ao norte do Círculo Ártico", "Permanece livre de gelo todo o ano devido à Corrente do Golfo", "Terminal ocidental da Rota Marítima do Norte", "Centro principal para exportação de carvão e fertilizantes", "Base da frota de quebra-gelos nucleares da Rússia"],
      fr: ["Situé sur la péninsule de Kola", "Plus grand port au monde au nord du cercle polaire", "Libre de glaces toute l'année grâce au Gulf Stream", "Terminus occidental de la route maritime du Nord", "Centre majeur d'exportation de charbon et d'engrais", "Base de la flotte de brise-glaces nucléaires de Russie"],
