      pt: ["Fundada em 1933", "Localizada em Chelyabinsk", "Conhecida como 'Tankograd' durante a 2ª Guerra Mundial", "Produziu tanques KV-1, IS-2 e T-34", "Fabrica escavadoras pesadas e assentadores de tubos", "Crucial para o desenvolvimento da infraestrutura siberiana"],
      fr: ["Fondée en 1933", "Située à Tcheliabinsk", "Nommée 'Tankograd' pendant la Seconde Guerre mondiale", "A produit les chars KV-1, IS-2 et T-34", "Fabrique des bulldozers lourds et poseurs de canalisations", "Cruciale pour le développement des infrastructures sibériennes"],
