      pt: ["Localizada em Volzhsky, Oblast de Volgogrado", "Fundada em 1970", "Subsidiária principal do Grupo TMK", "Especializada em tubos sem costura e de grande diâmetro", "Crucial para a indústria do petróleo e gás"],
