    name: { de: "Kernkraftwerk Bilibino", hu: "Bilibinói atomerőmű", ro: "Centrala nucleară Bilibino", en: "Bilibino Nuclear Power Plant"},
    image: "/poi-images/russia-bilibino-nuclear-economic-v2.webp",
