      de: ["Nördlichstes AKW", "Region Tschukotka", "Permafrostboden", "Kleinstes AKW Russlands"],
      hu: ["A legészakibb atomerőmű", "Csukcsföld", "Permafrost terület", "Oroszország legkisebb atomerőműve"],
      ro: ["Cea mai nordică centrală", "Regiunea Ciukotka", "Zonă de permafrost", "Cea mai mică centrală nucleară rusă"],
