      es: ["Central más septentrional", "Región de Chukotka", "Suelo de permafrost", "Central más pequeña de Rusia"],
      pt: ["Central mais a norte", "Região de Chukotka", "Solo permafrost", "Central nuclear mais pequena da Rússia"],
