      fr: ["Fondé en 1703 par Pierre le Grand", "Plus grand port à conteneurs de Russie", "Situé dans la baie de la Néva (golfe de Finlande)", "Porte d'entrée clé vers l'Europe et l'Amérique du Nord", "Traite des biens de consommation, du bois et des métaux", "Relié directement à la voie navigable Volga-Baltique"],
