      hu: ["Szalehardot 1595-ben alapították, 1933-ig Obdorszk néven volt ismert", "Ez az egyetlen város a világon, amely közvetlenül a 66. szélességi körön fekszik", "A kikötő összeköti az Ob folyó hajózását a Jeges-tengerrel", "Télen a hőmérséklet -50 Celsius-fok alá is süllyedhet", "Szalehardnak nincs állandó vasúti összeköttetése a központi orosz hálózattal", "A kikötő a gázipar számára érkező berendezések fontos rakodóhelye"],
      ro: ["Salehard a fost fondat în 1595 și s-a numit Obdorsk până în 1933", "Este singurul oraș din lume situat exact pe paralela de 66 de grade nord", "Portul face legătura între navigația fluvială de pe Ob și Oceanul Arctic", "Temperaturile pe timp de iarnă pot scădea sub -50 de grade Celsius", "Salehard nu are o conexiune feroviară permanentă cu rețeaua centrală rusă", "Portul este un punct de transfer major pentru echipamentele industriei de gaze"],
      en: ["Salekhard was founded in 1595 and known as Obdorsk until 1933", "It is the only city in the world located directly on the 66th parallel", "The port links Ob River navigation with the Arctic Ocean routes", "Winter temperatures in the region can drop below -50 degrees Celsius", "Salekhard lacks a permanent rail connection to the central Russian network", "The port serves as a critical transshipment point for gas industry equipment"],
