      pt: ["O porto foi construído na década de 1950.", "A temporada de navegação dura 4 a 5 meses.", "Capacidade de transbordo de 1 milhão de toneladas por ano.", "Profundidade da água nos cais de até 8 metros.", "O porto localiza-se a 66° de latitude norte.", "A navegação é apoiada por quebra-gelos."],
      fr: ["Le port a été construit dans les années 1950.", "La saison de navigation dure 4 à 5 mois.", "Capacité de transbordement d'un million de tonnes par an.", "Profondeur d'eau aux quais allant jusqu'à 8 mètres.", "Le port est situé à 66° de latitude nord.", "La navigation est assistée par brise-glace."],
